<?php
return function (Router $r) {
    $r->get('/lessons',fn()=>View::render(__DIR__.'/views/index.php',['title'=>'Lessons & growth','lessons'=>Db::all("SELECT l.*,t.status task_status FROM lessons l LEFT JOIN tasks t ON t.id=l.task_id ORDER BY (l.status='verified'),l.created_at DESC,l.id DESC"),'tasks'=>Db::all("SELECT * FROM tasks WHERE status='open' ORDER BY due IS NULL,due,id"),'completed'=>Db::all("SELECT * FROM tasks WHERE status='done' ORDER BY id DESC LIMIT 30"),'repeated'=>LessonService::repeated()]));
    $r->post('/lessons',function () { LessonService::add(['area'=>text_input('area'),'what_happened'=>text_input('what_happened',3000),'root_cause'=>text_input('root_cause',3000,false),'lesson'=>text_input('lesson',3000,false),'action'=>text_input('action',200,false),'due'=>$_POST['due'] ?? '']); return redirect('/lessons','Lesson saved. If you added an action, its task is ready.'); });
    $r->post('/lessons/{id}/status',function ($p) { LessonService::status(record_id($p['id']),text_input('status')); return redirect('/lessons','Lesson updated.'); });
    $r->post('/lessons/{id}/delete',function ($p) { LessonService::delete(record_id($p['id'])); return redirect('/lessons','Lesson and its action task removed.'); });
    $r->post('/tasks',function () { Db::run('INSERT INTO tasks(title,due,source) VALUES (?,?,?)',[text_input('title'),optional_date($_POST['due'] ?? ''),'manual']); return redirect('/lessons','Task added.'); });
    $r->post('/tasks/{id}/done',function ($p) { LessonService::completeTask(record_id($p['id'])); $back=$_POST['return_to'] ?? '/lessons'; return redirect(in_array($back,['/','/lessons','/review'],true) ? $back : '/lessons','Task completed.'); });
    $r->post('/tasks/{id}/reopen',function ($p) { LessonService::reopenTask(record_id($p['id'])); return redirect('/lessons','Task reopened.'); });
    $r->get('/review',function () { $week=LessonService::weekId(); return View::render(__DIR__.'/views/review.php',['title'=>'Weekly review','week'=>$week,'current'=>Db::one('SELECT * FROM weekly_reviews WHERE week=?',[$week]),'history'=>Db::all('SELECT * FROM weekly_reviews ORDER BY week DESC LIMIT 12'),'openLessons'=>Db::all("SELECT * FROM lessons WHERE status='open' ORDER BY created_at"),'tasks'=>Db::all("SELECT * FROM tasks WHERE status='open' ORDER BY (source='lesson') DESC,due IS NULL,due")]); });
    $r->post('/review',function () { LessonService::review(['wins'=>text_input('wins',5000,false),'fails'=>text_input('fails',5000,false),'score'=>$_POST['score'] ?? '', 'focus'=>text_input('focus',1000,false)]); return redirect('/review','Weekly review saved.'); });
};
